def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: dict[str, bool] = {}
    history: list[tuple] = []  # revert instructions for successful ops
    rejected: list[int] = []

    def valid_amount(s: str) -> bool:
        return len(s) > 0 and s.isdigit()

    for i, op in enumerate(ops):
        toks = op.split(" ")
        verb = toks[0] if toks else ""
        ok = False

        if verb == "undo" and len(toks) == 1:
            if history:
                undo_op = history.pop()
                kind = undo_op[0]
                if kind == "open":
                    a = undo_op[1]
                    del balances[a]
                    del frozen[a]
                elif kind == "deposit":
                    _, a, n = undo_op
                    balances[a] -= n
                elif kind == "withdraw":
                    _, a, n = undo_op
                    balances[a] += n
                elif kind == "transfer":
                    _, a, b, n = undo_op
                    balances[a] += n
                    balances[b] -= n
                elif kind == "freeze":
                    frozen[undo_op[1]] = False
                elif kind == "unfreeze":
                    frozen[undo_op[1]] = True
                ok = True

        elif verb == "open" and len(toks) == 3 and valid_amount(toks[2]):
            a, n = toks[1], int(toks[2])
            if a not in balances:
                balances[a] = n
                frozen[a] = False
                history.append(("open", a))
                ok = True

        elif verb == "deposit" and len(toks) == 3 and valid_amount(toks[2]):
            a, n = toks[1], int(toks[2])
            if a in balances and n > 0:
                balances[a] += n
                history.append(("deposit", a, n))
                ok = True

        elif verb == "withdraw" and len(toks) == 3 and valid_amount(toks[2]):
            a, n = toks[1], int(toks[2])
            if a in balances and not frozen[a] and n > 0 and balances[a] >= n:
                balances[a] -= n
                history.append(("withdraw", a, n))
                ok = True

        elif verb == "transfer" and len(toks) == 4 and valid_amount(toks[3]):
            a, b, n = toks[1], toks[2], int(toks[3])
            if (a != b and a in balances and b in balances
                    and not frozen[a] and n > 0 and balances[a] >= n):
                balances[a] -= n
                balances[b] += n
                history.append(("transfer", a, b, n))
                ok = True

        elif verb == "freeze" and len(toks) == 2:
            a = toks[1]
            if a in balances and not frozen[a]:
                frozen[a] = True
                history.append(("freeze", a))
                ok = True

        elif verb == "unfreeze" and len(toks) == 2:
            a = toks[1]
            if a in balances and frozen[a]:
                frozen[a] = False
                history.append(("unfreeze", a))
                ok = True

        if not ok:
            rejected.append(i)

    return balances, rejected
